from __future__ import annotations
import html
import json
from .catalog import SURFACES, PHASES, CONTEXTS, STATUSES

def esc(value): return html.escape(str(value), quote=True)

def render_report(r):
    c = r["config"]
    rows = "".join(f'<tr><td>{esc(e["title"])}</td><td>{esc(STATUSES[e["status"]])}</td><td>{esc(e["explanation"])}</td></tr>' for e in r["evidence"])
    details = "".join(f'<details><summary>{esc(e["title"])}</summary><p>{esc(e["captured_at_utc"])} · {esc(e["kind"])} · {esc(e["confidence"])}</p><pre>{esc(json.dumps(e["value"],ensure_ascii=False,indent=2))}</pre><p>{esc(" / ".join(e["limitations"]))}</p><p>来源：{esc(e["source"]["url"])}<br>取回：{esc(e["source"]["retrieved_on"])}；版本：{esc(e["source"]["revision"])}</p></details>' for e in r["evidence"])
    samples = "".join('<tr>'+"".join(f'<td>{esc(s.get(k) if s.get(k) is not None else "未知")}</td>' for k in ("elapsed_ms", "status", "target_count", "rss_mb", "cpu_capacity_percent", "established_count"))+'</tr>' for s in r["samples"])
    return f'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; base-uri 'none'; form-action 'none'"><title>CC Environment Auditor · 本地报告</title><style>
body{{margin:0;background:#f3f6fa;color:#1d2d44;font:16px/1.7 'Segoe UI','Microsoft YaHei UI',sans-serif}}main{{max-width:1100px;margin:auto;padding:48px 32px}}h1{{font-size:32px;margin:0}}.sub{{color:#55647a}}section,details{{background:white;padding:22px;margin:18px 0;border:1px solid #d8e0eb;border-radius:12px}}table{{width:100%;border-collapse:collapse;font-size:14px}}th,td{{padding:12px;text-align:left;border-bottom:1px solid #e3e9f1;vertical-align:top}}summary{{cursor:pointer;font-weight:600}}pre{{white-space:pre-wrap;overflow-wrap:anywhere;background:#f4f7fa;padding:16px}}p{{overflow-wrap:anywhere}}.notice{{border-left:4px solid #4774aa}}summary:focus-visible{{outline:3px solid #4774aa}}@media(max-width:700px){{main{{padding:20px}}table{{display:block;overflow:auto}}}}</style></head><body><main><h1>CC Environment Auditor</h1><p class="sub">{esc(SURFACES[c['surface']])} / {esc(c['subtype'])} · {esc(PHASES[c['phase']])} · {esc(CONTEXTS[c['context']])}</p><section class="notice"><strong>证据与覆盖范围</strong><p>政策资格未评估；账户结果与服务端决策未知。阶段标签由用户声明，审计器观测不代表 Claude 服务器视角。</p><p>状态：{esc(r['state'])}；实际时长 {r['duration_ms']/1000:.2f} 秒；样本 {len(r['samples'])} 个。{'此报告使用合成测试数据。' if r['synthetic'] else ''}</p></section><p>开始 {esc(r['started_at_utc'])}<br>结束 {esc(r['finished_at_utc'])}<br>版本 {esc(r['version'])}；运行 ID {esc(r['run_id'])}</p><section><table><caption>本次诊断结果</caption><thead><tr><th>项目</th><th>覆盖状态</th><th>解释</th></tr></thead><tbody>{rows}</tbody></table></section><section><h2>采样时间线</h2><table><thead><tr><th>毫秒</th><th>状态</th><th>目标进程</th><th>内存 MB</th><th>CPU 总容量 %</th><th>已建立 TCP</th></tr></thead><tbody>{samples}</tbody></table></section><h2>证据详情</h2>{details}<section><h2>限制</h2><ul>{''.join('<li>'+esc(x)+'</li>' for x in r['limitations'])}</ul><p>代码 SHA-256：{esc(r['source_sha256'])}</p><p>本地完整性校验不证明提供方真实性；此报告没有自动上传功能。</p></section></main></body></html>'''
